// Package main is the entry point for the AI.YOU CLI application.
package main

import (
	"context"
	"os"
	"os/signal"
	"syscall"

	"github.com/chrlesur/aiyou.cli/internal/cli"
	"github.com/chrlesur/aiyou.cli/internal/config"
	"github.com/sirupsen/logrus"
)

// main initializes and starts the AI.YOU CLI application.
// It handles graceful shutdown and proper error management.
func main() {
	// Create context with cancellation for graceful shutdown
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Initialize configuration
	cfg, err := config.Load()
	if err != nil {
		logrus.Fatalf("Failed to load configuration: %v", err)
	}

	// Initialize logger
	logger := cli.NewLogger(cfg.LogLevel)
	logger.Info("Starting AI.YOU CLI")

	// Setup signal handling for graceful shutdown
	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)

	// Initialize CLI application
	app, err := cli.NewApp(cfg, logger)
	if err != nil {
		logger.Fatalf("Failed to initialize CLI application: %v", err)
	}

	// Start the application
	go func() {
		if err := app.Run(ctx); err != nil {
			logger.Errorf("Application error: %v", err)
			cancel()
		}
	}()

	// Wait for shutdown signal
	<-sigChan
	logger.Info("Shutting down gracefully...")
	cancel()
}

// internal/cache/example_test.go
package cache_test

import (
	"context"
	"fmt"
	"log"
	"time"

	"github.com/chrlesur/aiyou.cli/internal/cache"
	"github.com/chrlesur/aiyou.cli/internal/cache/memory"
)

func Example() {
	// Création d'un nouveau cache avec la configuration par défaut
	config := cache.DefaultConfig()
	c, err := memory.NewMemoryCache(config)
	if err != nil {
		log.Fatal(err)
	}
	defer c.Close()

	ctx := context.Background()

	// Stockage d'une valeur
	err = c.Set(ctx, "greeting", "Hello, World!", cache.QueryCache)
	if err != nil {
		log.Fatal(err)
	}

	// Récupération de la valeur
	entry, exists := c.Get(ctx, "greeting")
	if exists {
		fmt.Println(entry.Value)
	}
	// Output: Hello, World!
}

func Example_withExpiration() {
	config := cache.DefaultConfig()
	config.QueryTTL = 1 * time.Second
	c, _ := memory.NewMemoryCache(config)
	defer c.Close()

	ctx := context.Background()

	c.Set(ctx, "temp", "temporary value", cache.QueryCache)

	entry, exists := c.Get(ctx, "temp")
	fmt.Printf("Immediately: %v\n", exists)

	time.Sleep(2 * time.Second)

	entry, exists = c.Get(ctx, "temp")
	fmt.Printf("After expiration: %v\n", exists)

	// Output:
	// Immediately: true
	// After expiration: false
}

// Package api provides the core API interaction layer for the AI.YOU CLI.
package api

import (
	"context"
	"errors"
	"fmt"
	"sync"

	"github.com/chrlesur/aiyou.cli/internal/cache"
	"github.com/chrlesur/aiyou.cli/internal/config"
	"github.com/chrlesur/aiyou.cli/internal/interfaces"
	"github.com/chrlesur/aiyou.golib/pkg/aiyou"
	"github.com/sirupsen/logrus"
)

var (
	ErrAssistantNotFound  = errors.New("assistant not found")
	ErrInvalidAssistantID = errors.New("invalid assistant ID")
)

// AssistantManager handles operations related to AI assistants.
type AssistantManager struct {
	client interfaces.AIClient
	cache  cache.Cache
	config *config.Config
	logger *logrus.Logger
	mu     sync.RWMutex

	// Cache des assistants sélectionnés par l'utilisateur
	selectedAssistant string
}

// AssistantManagerConfig holds configuration for creating a new AssistantManager.
type AssistantManagerConfig struct {
	Client interfaces.AIClient
	Cache  cache.Cache
	Config *config.Config
	Logger *logrus.Logger
}

// NewAssistantManager creates a new instance of AssistantManager.
func NewAssistantManager(cfg AssistantManagerConfig) (*AssistantManager, error) {
	if cfg.Client == nil {
		return nil, errors.New("client is required")
	}
	if cfg.Cache == nil {
		return nil, errors.New("cache is required")
	}
	if cfg.Config == nil {
		return nil, errors.New("config is required")
	}
	if cfg.Logger == nil {
		return nil, errors.New("logger is required")
	}

	return &AssistantManager{
		client: cfg.Client,
		cache:  cfg.Cache,
		config: cfg.Config,
		logger: cfg.Logger,
	}, nil
}

// ListAssistants retrieves the list of available assistants.
func (am *AssistantManager) ListAssistants(ctx context.Context) ([]aiyou.Assistant, error) {
	// Vérifier l'authentification
	if !am.client.IsAuthenticated() {
		return nil, ErrNotAuthenticated
	}

	// Vérifier le cache
	cacheKey := "assistants:list"
	if entry, exists := am.cache.Get(ctx, cacheKey); exists {
		if assistants, ok := entry.Value.([]aiyou.Assistant); ok {
			am.logger.Debug("Using cached assistants list")
			return assistants, nil
		}
	}

	// Appeler l'API
	response, err := am.client.GetUserAssistants(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get assistants: %w", err)
	}

	// Mettre en cache
	err = am.cache.Set(ctx, cacheKey, response.Members, cache.AssistantCache)
	if err != nil {
		am.logger.WithError(err).Warn("Failed to cache assistants list")
	}

	return response.Members, nil
}

// GetAssistant retrieves information about a specific assistant.
func (am *AssistantManager) GetAssistant(ctx context.Context, assistantID string) (*aiyou.Assistant, error) {
	if assistantID == "" {
		return nil, ErrInvalidAssistantID
	}

	assistants, err := am.ListAssistants(ctx)
	if err != nil {
		return nil, err
	}

	for _, assistant := range assistants {
		if assistant.ID == assistantID {
			return &assistant, nil
		}
	}

	return nil, ErrAssistantNotFound
}

// SelectAssistant sets the specified assistant as the currently selected one.
func (am *AssistantManager) SelectAssistant(ctx context.Context, assistantID string) error {
	assistant, err := am.GetAssistant(ctx, assistantID)
	if err != nil {
		return err
	}

	am.mu.Lock()
	am.selectedAssistant = assistant.ID
	am.mu.Unlock()

	// Sauvegarder la préférence dans le cache
	err = am.cache.Set(ctx, "selected_assistant", assistant.ID, cache.UserCache)
	if err != nil {
		am.logger.WithError(err).Warn("Failed to cache selected assistant")
	}

	return nil
}

// GetSelectedAssistant returns the currently selected assistant.
func (am *AssistantManager) GetSelectedAssistant(ctx context.Context) (*aiyou.Assistant, error) {
	am.mu.RLock()
	assistantID := am.selectedAssistant
	am.mu.RUnlock()

	if assistantID == "" {
		// Essayer de récupérer depuis le cache
		if entry, exists := am.cache.Get(ctx, "selected_assistant"); exists {
			if id, ok := entry.Value.(string); ok {
				assistantID = id
			}
		}
	}

	if assistantID == "" {
		return nil, errors.New("no assistant selected")
	}

	return am.GetAssistant(ctx, assistantID)
}

package api

import (
	"context"
	"errors"
	"io"
	"testing"
	"time"

	"github.com/chrlesur/aiyou.cli/internal/cache"
	"github.com/chrlesur/aiyou.cli/internal/cache/memory"
	"github.com/chrlesur/aiyou.cli/internal/config"
	"github.com/chrlesur/aiyou.golib/pkg/aiyou"
	"github.com/sirupsen/logrus"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func setupAssistantTest(t *testing.T) (*AssistantManager, *MockClient, cache.Cache, func()) {
	logger := logrus.New()
	logger.SetOutput(io.Discard)

	mockClient := &MockClient{}

	cacheConfig := cache.DefaultConfig()
	cacheConfig.CleanupInterval = time.Second
	memCache, err := memory.NewMemoryCache(cacheConfig)
	require.NoError(t, err)

	cfg := &config.Config{
		APIEndpoint: "https://test.api.aiyou.cloud",
		MaxThreads:  4,
	}

	am, err := NewAssistantManager(AssistantManagerConfig{
		Client: mockClient,
		Cache:  memCache,
		Config: cfg,
		Logger: logger,
	})
	require.NoError(t, err)

	cleanup := func() {
		memCache.Close()
	}

	return am, mockClient, memCache, cleanup
}

func TestAssistantManager_ListAssistants(t *testing.T) {
	ctx := context.Background()

	tests := []struct {
		name          string
		setupMock     func(*MockClient)
		wantErr       bool
		expectedCount int
		checkCache    bool
	}{
		{
			name: "successful list",
			setupMock: func(mockClient *MockClient) {
				mockClient.IsAuthenticatedFn = func() bool { return true }
				mockClient.GetUserAssistantsFn = func(ctx context.Context) (*aiyou.AssistantsResponse, error) {
					return &aiyou.AssistantsResponse{
						TotalItems: 2,
						Members: []aiyou.Assistant{
							{
								ID:    "asst_1",
								Name:  "Assistant 1",
								Model: "gpt-4",
							},
							{
								ID:    "asst_2",
								Name:  "Assistant 2",
								Model: "gpt-3.5-turbo",
							},
						},
					}, nil
				}
			},
			wantErr:       false,
			expectedCount: 2,
			checkCache:    true,
		},
		{
			name: "unauthenticated",
			setupMock: func(mockClient *MockClient) {
				mockClient.IsAuthenticatedFn = func() bool { return false }
			},
			wantErr:       true,
			expectedCount: 0,
			checkCache:    false,
		},
		{
			name: "api error",
			setupMock: func(mockClient *MockClient) {
				mockClient.IsAuthenticatedFn = func() bool { return true }
				mockClient.GetUserAssistantsFn = func(ctx context.Context) (*aiyou.AssistantsResponse, error) {
					return nil, errors.New("API error")
				}
			},
			wantErr:       true,
			expectedCount: 0,
			checkCache:    false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			am, mockClient, cache, cleanup := setupAssistantTest(t)
			defer cleanup()

			if tt.setupMock != nil {
				tt.setupMock(mockClient)
			}

			err := cache.Clear(ctx)
			require.NoError(t, err)

			assistants, err := am.ListAssistants(ctx)
			if tt.wantErr {
				assert.Error(t, err)
				assert.Nil(t, assistants)
			} else {
				assert.NoError(t, err)
				assert.Len(t, assistants, tt.expectedCount)

				if tt.checkCache {
					cacheEntry, exists := cache.Get(ctx, "assistants:list")
					assert.True(t, exists)
					cachedAssistants, ok := cacheEntry.Value.([]aiyou.Assistant)
					assert.True(t, ok)
					assert.Len(t, cachedAssistants, tt.expectedCount)
				}
			}
		})
	}
}

func TestAssistantManager_GetAssistant(t *testing.T) {
	ctx := context.Background()

	tests := []struct {
		name        string
		assistantID string
		setupMock   func(*MockClient)
		wantErr     bool
		errType     error
	}{
		{
			name:        "existing assistant",
			assistantID: "asst_1",
			setupMock: func(mockClient *MockClient) {
				mockClient.IsAuthenticatedFn = func() bool { return true }
				mockClient.GetUserAssistantsFn = func(ctx context.Context) (*aiyou.AssistantsResponse, error) {
					return &aiyou.AssistantsResponse{
						Members: []aiyou.Assistant{
							{
								ID:    "asst_1",
								Name:  "Test Assistant",
								Model: "gpt-4",
							},
						},
					}, nil
				}
			},
			wantErr: false,
		},
		{
			name:        "empty assistant ID",
			assistantID: "",
			setupMock: func(mockClient *MockClient) {
				mockClient.IsAuthenticatedFn = func() bool { return true }
			},
			wantErr: true,
			errType: ErrInvalidAssistantID,
		},
		{
			name:        "non-existent assistant",
			assistantID: "asst_999",
			setupMock: func(mockClient *MockClient) {
				mockClient.IsAuthenticatedFn = func() bool { return true }
				mockClient.GetUserAssistantsFn = func(ctx context.Context) (*aiyou.AssistantsResponse, error) {
					return &aiyou.AssistantsResponse{
						Members: []aiyou.Assistant{},
					}, nil
				}
			},
			wantErr: true,
			errType: ErrAssistantNotFound,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			am, mockClient, cache, cleanup := setupAssistantTest(t)
			defer cleanup()

			if tt.setupMock != nil {
				tt.setupMock(mockClient)
			}

			err := cache.Clear(ctx)
			require.NoError(t, err)

			assistant, err := am.GetAssistant(ctx, tt.assistantID)
			if tt.wantErr {
				assert.Error(t, err)
				if tt.errType != nil {
					assert.ErrorIs(t, err, tt.errType)
				}
				assert.Nil(t, assistant)
			} else {
				assert.NoError(t, err)
				assert.NotNil(t, assistant)
				assert.Equal(t, tt.assistantID, assistant.ID)
			}
		})
	}
}

func TestAssistantManager_SelectAssistant(t *testing.T) {
	ctx := context.Background()

	tests := []struct {
		name        string
		assistantID string
		setupMock   func(*MockClient)
		wantErr     bool
		checkCache  bool
	}{
		{
			name:        "successful selection",
			assistantID: "asst_1",
			setupMock: func(mockClient *MockClient) {
				mockClient.IsAuthenticatedFn = func() bool { return true }
				mockClient.GetUserAssistantsFn = func(ctx context.Context) (*aiyou.AssistantsResponse, error) {
					return &aiyou.AssistantsResponse{
						Members: []aiyou.Assistant{
							{
								ID:    "asst_1",
								Name:  "Test Assistant",
								Model: "gpt-4",
							},
						},
					}, nil
				}
			},
			wantErr:    false,
			checkCache: true,
		},
		{
			name:        "invalid assistant ID",
			assistantID: "",
			setupMock: func(mockClient *MockClient) {
				mockClient.IsAuthenticatedFn = func() bool { return true }
			},
			wantErr:    true,
			checkCache: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			am, mockClient, cache, cleanup := setupAssistantTest(t)
			defer cleanup()

			if tt.setupMock != nil {
				tt.setupMock(mockClient)
			}

			err := cache.Clear(ctx)
			require.NoError(t, err)

			err = am.SelectAssistant(ctx, tt.assistantID)
			if tt.wantErr {
				assert.Error(t, err)
			} else {
				assert.NoError(t, err)

				// Vérifier que l'assistant est bien sélectionné
				selected, err := am.GetSelectedAssistant(ctx)
				assert.NoError(t, err)
				assert.Equal(t, tt.assistantID, selected.ID)

				if tt.checkCache {
					// Vérifier le cache
					cacheEntry, exists := cache.Get(ctx, "selected_assistant")
					assert.True(t, exists)
					assert.Equal(t, tt.assistantID, cacheEntry.Value)
				}
			}
		})
	}
}

// Package api provides the core API interaction layer for the AI.YOU CLI
package api

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"

	"github.com/chrlesur/aiyou.cli/internal/config"
	"github.com/chrlesur/aiyou.golib"
)

var (
	// ErrNotAuthenticated is returned when an operation requires authentication
	ErrNotAuthenticated = errors.New("not authenticated")
	// ErrInvalidCredentials is returned when login fails
	ErrInvalidCredentials = errors.New("invalid credentials")
	// ErrTokenExpired is returned when the current token has expired
	ErrTokenExpired = errors.New("token expired")
)

// AuthManager handles all authentication-related operations including
// token management and session state.
type AuthManager struct {
	mu     sync.RWMutex
	client *aiyou.Client
	cfg    *config.Config
	token  string
	expiry time.Time
}

// NewAuthManager creates a new authentication manager with the provided client and configuration.
// It initializes with default settings for token refresh behavior.
func NewAuthManager(client *aiyou.Client, cfg *config.Config) (*AuthManager, error) {
	if client == nil {
		return nil, errors.New("client is required")
	}
	if cfg == nil {
		return nil, errors.New("config is required")
	}

	return &AuthManager{
		client: client,
		cfg:    cfg,
	}, nil
}

// Login authenticates a user with the provided email and password.
// It returns an error if authentication fails or if the API is unavailable.
func (a *AuthManager) Login(ctx context.Context, email, password string) error {
	if ctx == nil {
		return errors.New("context is required")
	}
	if email == "" || password == "" {
		return errors.New("email and password are required")
	}

	// Create a new client with authentication
	client, err := aiyou.NewClient(email, password)
	if err != nil {
		if err.Error() == "invalid credentials" {
			return ErrInvalidCredentials
		}
		return fmt.Errorf("authentication failed: %w", err)
	}

	// Update internal state with new client
	a.mu.Lock()
	defer a.mu.Unlock()

	a.client = client
	a.expiry = time.Now().Add(24 * time.Hour)
	return nil
}

// GetToken returns the current authentication token.
// It returns an error if not authenticated.
func (a *AuthManager) GetToken(ctx context.Context) (string, error) {
	if ctx == nil {
		return "", errors.New("context is required")
	}

	a.mu.RLock()
	defer a.mu.RUnlock()

	if a.client == nil {
		return "", ErrNotAuthenticated
	}

	// Vérifier que le token n'a pas expiré
	if time.Now().After(a.expiry) {
		return "", ErrTokenExpired
	}

	return a.token, nil
}

// IsAuthenticated returns true if there is a valid authentication session.
func (a *AuthManager) IsAuthenticated() bool {
	a.mu.RLock()
	defer a.mu.RUnlock()

	return a.client != nil && time.Now().Before(a.expiry)
}

// Logout removes the current authentication session.
// It returns an error if the logout operation fails.
func (a *AuthManager) Logout() error {
	a.mu.Lock()
	defer a.mu.Unlock()

	if a.client == nil {
		return nil // Already logged out
	}

	// Reset all authentication state
	a.client = nil
	a.token = ""
	a.expiry = time.Time{}

	return nil
}

package api

import (
	"context"
	"testing"
	"time"

	"github.com/chrlesur/aiyou.cli/internal/config"
	"github.com/chrlesur/aiyou.golib"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestNewAuthManager(t *testing.T) {
	tests := []struct {
		name    string
		client  *aiyou.Client
		cfg     *config.Config
		wantErr bool
	}{
		{
			name:    "success with valid inputs",
			client:  &aiyou.Client{},
			cfg:     &config.Config{},
			wantErr: false,
		},
		{
			name:    "error with nil client",
			client:  nil,
			cfg:     &config.Config{},
			wantErr: true,
		},
		{
			name:    "error with nil config",
			client:  &aiyou.Client{},
			cfg:     nil,
			wantErr: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			manager, err := NewAuthManager(tt.client, tt.cfg)
			if tt.wantErr {
				assert.Error(t, err)
				assert.Nil(t, manager)
			} else {
				assert.NoError(t, err)
				assert.NotNil(t, manager)
			}
		})
	}
}

func TestAuthManager_Login(t *testing.T) {
	cfg := &config.Config{}
	validEmail := "test@example.com"
	validPassword := "password123"

	tests := []struct {
		name     string
		email    string
		password string
		setup    func(*testing.T) *aiyou.Client
		wantErr  bool
	}{
		{
			name:     "successful login",
			email:    validEmail,
			password: validPassword,
			setup: func(t *testing.T) *aiyou.Client {
				return &aiyou.Client{}
			},
			wantErr: false,
		},
		{
			name:     "empty email",
			email:    "",
			password: validPassword,
			setup: func(t *testing.T) *aiyou.Client {
				return &aiyou.Client{}
			},
			wantErr: true,
		},
		{
			name:     "empty password",
			email:    validEmail,
			password: "",
			setup: func(t *testing.T) *aiyou.Client {
				return &aiyou.Client{}
			},
			wantErr: true,
		},
		{
			name:     "nil context",
			email:    validEmail,
			password: validPassword,
			setup: func(t *testing.T) *aiyou.Client {
				return &aiyou.Client{}
			},
			wantErr: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			client := tt.setup(t)
			manager, err := NewAuthManager(client, cfg)
			require.NoError(t, err)

			ctx := context.Background()
			if tt.name == "nil context" {
				ctx = nil
			}

			err = manager.Login(ctx, tt.email, tt.password)
			if tt.wantErr {
				assert.Error(t, err)
			} else {
				assert.NoError(t, err)
				assert.True(t, manager.IsAuthenticated())
			}
		})
	}
}

func TestAuthManager_Logout(t *testing.T) {
	cfg := &config.Config{}
	client := &aiyou.Client{}

	tests := []struct {
		name    string
		setup   func(*AuthManager)
		wantErr bool
	}{
		{
			name: "successful logout when logged in",
			setup: func(am *AuthManager) {
				ctx := context.Background()
				_ = am.Login(ctx, "test@example.com", "password123")
			},
			wantErr: false,
		},
		{
			name: "successful logout when not logged in",
			setup: func(am *AuthManager) {
				// No setup needed - already logged out
			},
			wantErr: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			manager, err := NewAuthManager(client, cfg)
			require.NoError(t, err)

			if tt.setup != nil {
				tt.setup(manager)
			}

			err = manager.Logout()
			if tt.wantErr {
				assert.Error(t, err)
			} else {
				assert.NoError(t, err)
				assert.False(t, manager.IsAuthenticated())
			}
		})
	}
}

func TestAuthManager_GetToken(t *testing.T) {
	cfg := &config.Config{}
	client := &aiyou.Client{}

	tests := []struct {
		name      string
		setup     func(*AuthManager)
		wantErr   bool
		wantToken string
	}{
		{
			name: "get token when authenticated",
			setup: func(am *AuthManager) {
				ctx := context.Background()
				_ = am.Login(ctx, "test@example.com", "password123")
				// Simuler un token valide
				am.mu.Lock()
				am.token = "test-token"
				am.mu.Unlock()
			},
			wantErr:   false,
			wantToken: "test-token",
		},
		{
			name: "error when not authenticated",
