package api

import (
	"context"
	"errors"
	"fmt"
	"sync"

	"github.com/chrlesur/aiyou.cli/internal/cache"
	"github.com/chrlesur/aiyou.cli/internal/config"
	"github.com/chrlesur/aiyou.cli/internal/interfaces"
	"github.com/chrlesur/aiyou.golib/pkg/aiyou"
	"github.com/sirupsen/logrus"
)

var (
	ErrThreadNotFound      = errors.New("thread not found")
	ErrInvalidThreadID     = errors.New("invalid thread ID")
	ErrThreadLimitExceeded = errors.New("thread limit exceeded")
)

// ThreadManager handles operations related to conversation threads
type ThreadManager struct {
	client interfaces.AIClient
	cache  cache.Cache
	config *config.Config
	logger *logrus.Logger
	mu     sync.RWMutex
}

// ThreadManagerConfig holds configuration for creating a new ThreadManager
type ThreadManagerConfig struct {
	Client interfaces.AIClient
	Cache  cache.Cache
	Config *config.Config
	Logger *logrus.Logger
}

// NewThreadManager creates a new instance of ThreadManager
func NewThreadManager(cfg ThreadManagerConfig) (*ThreadManager, error) {
	if cfg.Client == nil {
		return nil, errors.New("client is required")
	}
	if cfg.Cache == nil {
		return nil, errors.New("cache is required")
	}
	if cfg.Config == nil {
		return nil, errors.New("config is required")
	}
	if cfg.Logger == nil {
		return nil, errors.New("logger is required")
	}

	return &ThreadManager{
		client: cfg.Client,
		cache:  cfg.Cache,
		config: cfg.Config,
		logger: cfg.Logger,
	}, nil
}

// CreateThread creates a new conversation thread
func (tm *ThreadManager) CreateThread(ctx context.Context) (*aiyou.ConversationThread, error) {
	if !tm.client.IsAuthenticated() {
		return nil, ErrNotAuthenticated
	}

	// Vérifier la limite des threads
	threads, err := tm.client.GetUserThreads(ctx, &aiyou.UserThreadsParams{})
	if err != nil {
		return nil, fmt.Errorf("failed to check thread limit: %w", err)
	}

	// Correction ici : utilisation de Threads au lieu de Conversations ou Members
	if len(threads.Threads) >= tm.config.MaxThreads {
		return nil, ErrThreadLimitExceeded
	}

	// Créer un nouveau thread via SaveConversation
	req := aiyou.SaveConversationRequest{
		IsNewAppThread: true,
	}
	resp, err := tm.client.SaveConversation(ctx, req)
	if err != nil {
		return nil, fmt.Errorf("failed to create thread: %w", err)
	}

	// Récupérer le thread créé
	thread, err := tm.client.GetConversation(ctx, resp.ID)
	if err != nil {
		return nil, fmt.Errorf("failed to get created thread: %w", err)
	}

	// Mettre à jour le cache
	cacheKey := fmt.Sprintf("thread:%s", thread.ID)
	err = tm.cache.Set(ctx, cacheKey, thread, cache.QueryCache)
	if err != nil {
		tm.logger.WithError(err).Warn("Failed to cache thread")
	}

	return thread, nil
}

// GetThread retrieves a specific conversation thread
func (tm *ThreadManager) GetThread(ctx context.Context, threadID string) (*aiyou.ConversationThread, error) {
	if threadID == "" {
		return nil, ErrInvalidThreadID
	}

	if !tm.client.IsAuthenticated() {
		return nil, ErrNotAuthenticated
	}

	// Vérifier le cache
	cacheKey := fmt.Sprintf("thread:%s", threadID)
	if entry, exists := tm.cache.Get(ctx, cacheKey); exists {
		if thread, ok := entry.Value.(*aiyou.ConversationThread); ok {
			return thread, nil
		}
	}

	// Récupérer depuis l'API
	thread, err := tm.client.GetConversation(ctx, threadID)
	if err != nil {
		return nil, fmt.Errorf("failed to get thread: %w", err)
	}

	// Mettre en cache
	err = tm.cache.Set(ctx, cacheKey, thread, cache.QueryCache)
	if err != nil {
		tm.logger.WithError(err).Warn("Failed to cache thread")
	}

	return thread, nil
}

// ListThreads retrieves a list of conversation threads with pagination
func (tm *ThreadManager) ListThreads(ctx context.Context, params *aiyou.UserThreadsParams) (*aiyou.UserThreadsOutput, error) {
	if !tm.client.IsAuthenticated() {
		return nil, ErrNotAuthenticated
	}

	// Vérifier le cache uniquement pour la première page sans recherche
	if params.Page == 1 && params.Search == "" {
		cacheKey := "threads:list"
		if entry, exists := tm.cache.Get(ctx, cacheKey); exists {
			if output, ok := entry.Value.(*aiyou.UserThreadsOutput); ok {
				return output, nil
			}
		}
	}

	// Récupérer depuis l'API
	output, err := tm.client.GetUserThreads(ctx, params)
	if err != nil {
		return nil, fmt.Errorf("failed to list threads: %w", err)
	}

	// Mettre en cache uniquement la première page sans recherche
	if params.Page == 1 && params.Search == "" {
		err = tm.cache.Set(ctx, "threads:list", output, cache.QueryCache)
		if err != nil {
			tm.logger.WithError(err).Warn("Failed to cache threads list")
		}
	}

	return output, nil
}

// DeleteThread deletes a conversation thread
func (tm *ThreadManager) DeleteThread(ctx context.Context, threadID string) error {
	if threadID == "" {
		return ErrInvalidThreadID
	}

	if !tm.client.IsAuthenticated() {
		return ErrNotAuthenticated
	}

	// Supprimer via l'API
	err := tm.client.DeleteThread(ctx, threadID)
	if err != nil {
		return fmt.Errorf("failed to delete thread: %w", err)
	}

	// Supprimer du cache
	cacheKey := fmt.Sprintf("thread:%s", threadID)
	err = tm.cache.Delete(ctx, cacheKey)
	if err != nil {
		tm.logger.WithError(err).Warn("Failed to remove thread from cache")
	}

	// Invalider le cache de la liste des threads
	err = tm.cache.Delete(ctx, "threads:list")
	if err != nil {
		tm.logger.WithError(err).Warn("Failed to invalidate threads list cache")
	}

	return nil
}

// Pour les tests uniquement
func (tm *ThreadManager) SetTestClient(client interfaces.AIClient) {
	tm.client = client
}

package api

import (
	"context"
	"fmt"
	"io"
	"testing"
	"time"

	"github.com/chrlesur/aiyou.cli/internal/cache"
	"github.com/chrlesur/aiyou.cli/internal/cache/memory"
	"github.com/chrlesur/aiyou.cli/internal/config"
	"github.com/chrlesur/aiyou.golib/pkg/aiyou"
	"github.com/sirupsen/logrus"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func setupThreadTest(t *testing.T) (*ThreadManager, *MockClient, cache.Cache, func()) {
	logger := logrus.New()
	logger.SetOutput(io.Discard)

	mockClient := &MockClient{}

	cacheConfig := cache.DefaultConfig()
	cacheConfig.CleanupInterval = time.Second
	memCache, err := memory.NewMemoryCache(cacheConfig)
	require.NoError(t, err)

	cfg := &config.Config{
		APIEndpoint: "https://test.api.aiyou.cloud",
		MaxThreads:  4,
	}

	tm, err := NewThreadManager(ThreadManagerConfig{
		Client: mockClient,
		Cache:  memCache,
		Config: cfg,
		Logger: logger,
	})
	require.NoError(t, err)

	cleanup := func() {
		memCache.Close()
	}

	return tm, mockClient, memCache, cleanup
}

func TestThreadManager_CreateThread(t *testing.T) {
	ctx := context.Background()

	tests := []struct {
		name      string
		setupMock func(*MockClient)
		wantErr   bool
		errType   error
	}{
		{
			name: "successful creation",
			setupMock: func(mockClient *MockClient) {
				mockClient.IsAuthenticatedFn = func() bool { return true }
				mockClient.GetUserThreadsFn = func(ctx context.Context, params *aiyou.UserThreadsParams) (*aiyou.UserThreadsOutput, error) {
					return &aiyou.UserThreadsOutput{
						Threads: []aiyou.ConversationThread{},
					}, nil
				}
				mockClient.SaveConversationFn = func(ctx context.Context, req aiyou.SaveConversationRequest) (*aiyou.SaveConversationResponse, error) {
					return &aiyou.SaveConversationResponse{
						ID: "thread_1",
					}, nil
				}
				mockClient.GetConversationFn = func(ctx context.Context, threadID string) (*aiyou.ConversationThread, error) {
					return &aiyou.ConversationThread{
						ID:        threadID,
						CreatedAt: time.Now(),
					}, nil
				}
			},
			wantErr: false,
		},
		{
			name: "unauthenticated",
			setupMock: func(mockClient *MockClient) {
				mockClient.IsAuthenticatedFn = func() bool { return false }
			},
			wantErr: true,
			errType: ErrNotAuthenticated,
		},
		{
			name: "thread limit exceeded",
			setupMock: func(mockClient *MockClient) {
				mockClient.IsAuthenticatedFn = func() bool { return true }
				mockClient.GetUserThreadsFn = func(ctx context.Context, params *aiyou.UserThreadsParams) (*aiyou.UserThreadsOutput, error) {
					threads := make([]aiyou.ConversationThread, 4)
					return &aiyou.UserThreadsOutput{Threads: threads}, nil
				}
			},
			wantErr: true,
			errType: ErrThreadLimitExceeded,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			tm, mockClient, cache, cleanup := setupThreadTest(t)
			defer cleanup()

			if tt.setupMock != nil {
				tt.setupMock(mockClient)
			}

			err := cache.Clear(ctx)
			require.NoError(t, err)

			thread, err := tm.CreateThread(ctx)
			if tt.wantErr {
				assert.Error(t, err)
				if tt.errType != nil {
					assert.ErrorIs(t, err, tt.errType)
				}
				assert.Nil(t, thread)
			} else {
				assert.NoError(t, err)
				assert.NotNil(t, thread)
				assert.NotEmpty(t, thread.ID)

				// Vérifier le cache
				cacheKey := fmt.Sprintf("thread:%s", thread.ID)
				entry, exists := cache.Get(ctx, cacheKey)
				assert.True(t, exists)
				cachedThread, ok := entry.Value.(*aiyou.ConversationThread)
				assert.True(t, ok)
				assert.Equal(t, thread.ID, cachedThread.ID)
			}
		})
	}
}

func TestThreadManager_ListThreads(t *testing.T) {
	ctx := context.Background()

	tests := []struct {
		name          string
		params        *aiyou.UserThreadsParams
		setupMock     func(*MockClient)
		wantErr       bool
		expectedCount int
		checkCache    bool
	}{
		{
			name:   "list first page",
			params: &aiyou.UserThreadsParams{Page: 1, ItemsPerPage: 10},
			setupMock: func(mockClient *MockClient) {
				mockClient.IsAuthenticatedFn = func() bool { return true }
				mockClient.GetUserThreadsFn = func(ctx context.Context, params *aiyou.UserThreadsParams) (*aiyou.UserThreadsOutput, error) {
					threads := make([]aiyou.ConversationThread, 2)
					return &aiyou.UserThreadsOutput{
						Threads:      threads,
						TotalItems:   2,
						ItemsPerPage: params.ItemsPerPage,
						CurrentPage:  params.Page,
					}, nil
				}
			},
			wantErr:       false,
			expectedCount: 2,
			checkCache:    true,
		},
		{
			name:   "unauthenticated",
			params: &aiyou.UserThreadsParams{Page: 1},
			setupMock: func(mockClient *MockClient) {
				mockClient.IsAuthenticatedFn = func() bool { return false }
			},
			wantErr:       true,
			expectedCount: 0,
			checkCache:    false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			tm, mockClient, cache, cleanup := setupThreadTest(t)
			defer cleanup()

			if tt.setupMock != nil {
				tt.setupMock(mockClient)
			}

			err := cache.Clear(ctx)
			require.NoError(t, err)

			output, err := tm.ListThreads(ctx, tt.params)
			if tt.wantErr {
				assert.Error(t, err)
				assert.Nil(t, output)
			} else {
				assert.NoError(t, err)
				assert.NotNil(t, output)
				assert.Len(t, output.Threads, tt.expectedCount)

				if tt.checkCache && tt.params.Page == 1 {
					cacheEntry, exists := cache.Get(ctx, "threads:list")
					assert.True(t, exists)
					cachedOutput, ok := cacheEntry.Value.(*aiyou.UserThreadsOutput)
					assert.True(t, ok)
					assert.Len(t, cachedOutput.Threads, tt.expectedCount)
				}
			}
		})
	}
}

func TestThreadManager_DeleteThread(t *testing.T) {
	ctx := context.Background()

	tests := []struct {
		name      string
		threadID  string
		setupMock func(*MockClient)
		wantErr   bool
		errType   error
	}{
		{
			name:     "successful deletion",
			threadID: "thread_1",
			setupMock: func(mockClient *MockClient) {
				mockClient.IsAuthenticatedFn = func() bool { return true }
				mockClient.DeleteThreadFn = func(ctx context.Context, threadID string) error {
					return nil
				}
			},
			wantErr: false,
		},
		{
			name:     "empty thread ID",
			threadID: "",
			setupMock: func(mockClient *MockClient) {
				mockClient.IsAuthenticatedFn = func() bool { return true }
			},
			wantErr: true,
			errType: ErrInvalidThreadID,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			tm, mockClient, cache, cleanup := setupThreadTest(t)
			defer cleanup()

			if tt.setupMock != nil {
				tt.setupMock(mockClient)
			}

			err := cache.Clear(ctx)
			require.NoError(t, err)

			err = tm.DeleteThread(ctx, tt.threadID)
			if tt.wantErr {
				assert.Error(t, err)
				if tt.errType != nil {
					assert.ErrorIs(t, err, tt.errType)
				}
			} else {
				assert.NoError(t, err)

				// Vérifier que le thread a été supprimé du cache
				cacheKey := fmt.Sprintf("thread:%s", tt.threadID)
				_, exists := cache.Get(ctx, cacheKey)
				assert.False(t, exists)
			}
		})
	}
}

